<script lang="ts">import type {WorkPackageQueueItem} from '../lib/multiWpScheduler.ts';export let queue:WorkPackageQueueItem[]=[];$: running=queue.filter(item=>item.status==='RUNNING').length;$: blocked=queue.filter(item=>item.status==='BLOCKED').length;$: waiting=queue.filter(item=>['PENDING','READY','REMEDIATION_PENDING'].includes(item.status)).length;$: next=queue.find(item=>item.status==='READY'||item.status==='PENDING');</script>
<section class="scheduler-status-projection" data-testid="scheduler-status-projection"><div class="section-label"><span>Scheduler Status</span><small>Read-only projection</small></div><div class="scheduler-status-grid"><div><span>Queue</span><strong>{waiting}</strong></div><div><span>Running</span><strong>{running}</strong></div><div><span>Blocked</span><strong>{blocked}</strong></div><div><span>Next Execution</span><strong>{next?.work_package_id??'NONE'}</strong></div></div></section>
